private void PageHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {


}

        double rastEvident = 0.00;
        double rastZbuluar = 0.00;
        double totalrast = 0.00;

        double rastEvident1 = 0.00;
        double rastZbuluar1 = 0.00;
        double totalrast1 = 0.00;


private void xrTableCell51_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 if (GetCurrentColumnValue("RASTEVIDENTUAR") == null || GetCurrentColumnValue("RASTEVIDENTUAR") == DBNull.Value) 
	xrTableCell51.Text = "0";
 else
	xrTableCell51.Text = Convert.ToInt32(GetCurrentColumnValue("RASTEVIDENTUAR")).ToString();
 rastEvident  += Convert.ToDouble(xrTableCell51.Text);
 rastEvident1 += Convert.ToDouble(xrTableCell51.Text);
}

private void xrTableCell53_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
  rastZbuluar += Convert.ToDouble(xrTableCell53.Text);
            rastZbuluar1 += Convert.ToDouble(xrTableCell53.Text);
}

private void xrTableCell72_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
  		if (rastEvident == 0)

                xrTableCell72.Text = "0.00";
            else

            {
                totalrast = (rastZbuluar / rastEvident) * 100;
                xrTableCell72.Text = String.Format("{0:#,#.00}", totalrast);
            }
            rastEvident = 0.00;
            rastZbuluar = 0.00;
            totalrast = 0.00;
}

private void xrTableCell80_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

            if (rastEvident1 == 0)

                xrTableCell80.Text = "0.00";
            else

            {
                totalrast1 = (rastZbuluar1 / rastEvident1) * 100;
                xrTableCell80.Text = String.Format("{0:#,#.00}", totalrast1);

             }
}

int counter  = 0;
private void xrTableCell61_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

	switch(counter)
	{
		case 1:
			xrTableCell61.Text = "I";
			break; 
		case 2:
			xrTableCell61.Text = "II";
			break;
		case 3:
			xrTableCell61.Text = "III";
			break;
		case 4:
			xrTableCell61.Text = "IV";
			break;
		case 5:
			xrTableCell61.Text = "V";
			break;
		case 6:
			xrTableCell61.Text = "VI";
			break;
		case 7:
			xrTableCell61.Text = "VII";
			break;
		case 8:
			xrTableCell61.Text = "VIII";
			break;
		case 9:
			xrTableCell61.Text = "IX";
			break;
		case 10:
			xrTableCell61.Text = "X";
			break;
		case 11:
			xrTableCell61.Text = "XI";
			break;
		case 12:
			xrTableCell61.Text = "XII";
			break;
		case 13:
			xrTableCell61.Text = "XIII";
			break;
		default:
			break;
	}

}

